CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('ADMIN','OPS_MANAGER','ENTRY_USER') NOT NULL DEFAULT 'ENTRY_USER',active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payments(id BIGINT AUTO_INCREMENT PRIMARY KEY,payment_date DATE NOT NULL,agent_name VARCHAR(150) NOT NULL,ecode VARCHAR(80),ops_manager VARCHAR(120),tl VARCHAR(120),atl_name VARCHAR(120),payment_mode VARCHAR(50) NOT NULL,usdt DECIMAL(18,6) NOT NULL DEFAULT 0,divided_by DECIMAL(18,6) NOT NULL DEFAULT 1,inr_amount DECIMAL(18,2) NOT NULL DEFAULT 0,received_in VARCHAR(120),cash_received DECIMAL(18,2) NOT NULL DEFAULT 0,remarks TEXT,created_by INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(payment_date),INDEX(ops_manager),INDEX(payment_mode),FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
